  `tindakan_kondisi_casing` text COLLATE utf8mb4_unicode_ci,
  `kebersihan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tindakan_kebersihan` text COLLATE utf8mb4_unicode_ci,
  `kabel_adaptor` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tindakan_kabel_adaptor` text COLLATE utf8mb4_unicode_ci,
  `lensa_proyektor` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tindakan_lensa_proyektor` text COLLATE utf8mb4_unicode_ci,
