  `fokus_zoom` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tindakan_fokus_zoom` text COLLATE utf8mb4_unicode_ci,
  `kecerahan_kontras` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tindakan_kecerahan_kontras` text COLLATE utf8mb4_unicode_ci,
  `koneksi_input_hdmi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `koneksi_input_vga` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `koneksi_input_usb` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `inspektor` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jabatan_inspektor` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
